def subtract(a, b):
    # Normalize and merge intervals
    def normalize(intervals):
        if not intervals:
            return []
        # Filter out empty intervals
        valid = [i for i in intervals if i[0] < i[1]]
        if not valid:
            return []
        # Sort by start position
        valid.sort()
        # Merge overlapping/touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add as new interval
                merged.append([start, end])
        return merged

    # Normalize both input sets
    a_norm = normalize(a)
    b_norm = normalize(b)

    if not a_norm:
        return []
    if not b_norm:
        return a_norm

    result = []

    # For each interval in a, subtract all intervals in b
    for a_start, a_end in a_norm:
        # Track the current range we're working with
        current_ranges = [[a_start, a_end]]

        # Subtract each interval in b from current ranges
        for b_start, b_end in b_norm:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # If b doesn't overlap with current range, keep it
                if b_end <= c_start or b_start >= c_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # b overlaps with current range
                    # Keep the part before b
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    # Keep the part after b
                    if b_end < c_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals in result
    if not result:
        return []
    result.sort()
    merged = [result[0]]
    for start, end in result[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

